describe('Bottom Sheet Mobile Dropdown Replacement', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport('iphone-x');
  });

  it('should display bottom sheet instead of dropdown on mobile viewport', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();

    cy.get('[data-testid="bottom-sheet"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="bottom-sheet"]').should('have.css', 'bottom', '0px');

    cy.get('[data-testid="dropdown-menu"]').should('not.exist');
  });

  it('should select option from bottom sheet and close it', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    cy.get('[data-testid="bottom-sheet-option"]').first().click();

    cy.get('[data-testid="bottom-sheet"]').should('not.be.visible');
    cy.get('[data-testid="dropdown-trigger"]').should('contain', 'Option 1');
  });

  it('should close bottom sheet when clicking backdrop', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    cy.get('[data-testid="bottom-sheet-backdrop"]').click({ force: true });

    cy.get('[data-testid="bottom-sheet"]').should('not.be.visible');
  });

  it('should close bottom sheet with close button', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    cy.get('[data-testid="bottom-sheet-close-btn"]').click();

    cy.get('[data-testid="bottom-sheet"]').should('not.be.visible');
  });

  it('should scroll through options in bottom sheet when list is long', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    cy.get('[data-testid="bottom-sheet-options-list"]').should('have.css', 'overflow-y', 'auto');

    cy.get('[data-testid="bottom-sheet-options-list"]').scrollTo('bottom');
    cy.get('[data-testid="bottom-sheet-option"]').last().should('be.visible');
  });

  it('should display dropdown normally on desktop viewport', () => {
    cy.viewport(1280, 720);
    cy.get('[data-testid="dropdown-trigger"]').click();

    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet"]').should('not.exist');
  });

  it('should handle keyboard escape key to close bottom sheet', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');

    cy.get('body').type('{esc}');

    cy.get('[data-testid="bottom-sheet"]').should('not.be.visible');
  });

  it('should maintain selected value after closing and reopening bottom sheet', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet-option"]').eq(2).click();
    cy.get('[data-testid="dropdown-trigger"]').should('contain', 'Option 3');

    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet-option"]').eq(2).should('have.attr', 'aria-selected', 'true');
  });

  it('should handle disabled options in bottom sheet', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();

    cy.get('[data-testid="bottom-sheet-option"][disabled]').should('have.css', 'opacity', '0.5');
    cy.get('[data-testid="bottom-sheet-option"][disabled]').click({ force: true });

    cy.get('[data-testid="dropdown-trigger"]').should('not.contain', 'Disabled Option');
  });

  it('should search/filter options in bottom sheet', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="bottom-sheet-search"]').should('be.visible');

    cy.get('[data-testid="bottom-sheet-search"]').type('Option 2');

    cy.get('[data-testid="bottom-sheet-option"]').should('have.length', 1);
    cy.get('[data-testid="bottom-sheet-option"]').should('contain', 'Option 2');
  });

  it('should handle empty state in bottom sheet', () => {
    cy.get('[data-testid="dropdown-trigger-empty"]').click();

    cy.get('[data-testid="bottom-sheet"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet-empty-state"]').should('be.visible');
    cy.get('[data-testid="bottom-sheet-empty-state"]').should('contain', 'No options available');
  });
});
